def pipe_line(tiles):
    last=None; bad=[]
    for (x,y) in tiles:
        if last is None or abs(last[0]-x)+abs(last[1]-y)>6:
            move_to(Position(x=x+1,y=y)); last=(x,y)
        try:
            if can_place_entity(Prototype.Pipe, position=Position(x=x,y=y)):
                place_entity(Prototype.Pipe, position=Position(x=x,y=y))
        except Exception as ex: bad.append((x,y,str(ex)[:60]))
    return bad
